-- Portal Transparansi PN Natuna, article id 8 only
START TRANSACTION;
UPDATE pnn_content
SET introtext = '<div class="trans-page"><header class="trans-hero"><div><span class="trans-kicker">Portal Informasi Publik</span><h2>Transparansi &amp; Akuntabilitas</h2><p>Temukan laporan kinerja, keuangan, integritas, dan keterbukaan informasi Pengadilan Negeri Natuna dalam satu portal.</p></div><svg class="trans-illus" aria-hidden="true" viewBox="0 0 220 170" fill="none"><path d="M40 20h100l35 35v95H40z" stroke="currentColor" stroke-width="4"/><path d="M140 20v38h38M67 79h74M67 101h52" stroke="currentColor" stroke-width="4"/><path d="M145 99l25-10 25 10v20c0 18-10 29-25 36-15-7-25-18-25-36z" fill="currentColor" opacity=".2"/><path d="m158 120 8 8 17-19" stroke="currentColor" stroke-width="5"/></svg></header><nav class="trans-nav" aria-label="Kelompok informasi transparansi"><a href="#kinerja">Kinerja & Perencanaan</a><a href="#keuangan">Keuangan & Pengadaan</a><a href="#integritas">Integritas & Kualitas Layanan</a><a href="#informasi">Keterbukaan Informasi</a></nav><section class="trans-section" id="kinerja" aria-labelledby="trans-kinerja"><header class="trans-section-head"><span>01</span><div><h2 id="trans-kinerja">Kinerja & Perencanaan</h2><p>Dokumen sasaran, capaian, dan pertanggungjawaban kinerja.</p></div></header><div class="trans-grid"><a class="trans-card" href="/laporan-tahunan"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan Tahunan</h3><p>Publikasi capaian dan pelaksanaan program tahunan.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/ringkasan-lkjip"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Ringkasan LKjIP</h3><p>Ringkasan akuntabilitas kinerja instansi pemerintah.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/sakip"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>SAKIP</h3><p>Dokumen sistem akuntabilitas kinerja instansi.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a></div></section><section class="trans-section" id="keuangan" aria-labelledby="trans-keuangan"><header class="trans-section-head"><span>02</span><div><h2 id="trans-keuangan">Keuangan & Pengadaan</h2><p>Pelaporan anggaran, keuangan, dan proses pengadaan.</p></div></header><div class="trans-grid"><a class="trans-card" href="/laporan-realisasi-anggaran"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan Realisasi Anggaran DIPA 01 dan 03</h3><p>Realisasi anggaran badan peradilan dan teknis yudisial.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/laporan-keuangan"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan Keuangan PN</h3><p>Laporan posisi dan pengelolaan keuangan satuan kerja.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/lelang-barang-jasa"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Lelang Barang dan Jasa</h3><p>Informasi pengadaan serta pelelangan barang dan jasa.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a></div></section><section class="trans-section" id="integritas" aria-labelledby="trans-integritas"><header class="trans-section-head"><span>03</span><div><h2 id="trans-integritas">Integritas & Kualitas Layanan</h2><p>Publikasi integritas serta pengukuran mutu pelayanan.</p></div></header><div class="trans-grid"><a class="trans-card" href="/lhkpn"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>LHKPN</h3><p>Informasi pelaporan harta kekayaan penyelenggara negara.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/laporan-skm"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan SKM</h3><p>Hasil Survei Kepuasan Masyarakat atas layanan pengadilan.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/laporan-spak"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan SPAK</h3><p>Hasil Survei Persepsi Anti Korupsi pada layanan.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/laporan-survei-harian"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan Survei Harian</h3><p>Rekap umpan balik harian pengguna layanan.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a></div></section><section class="trans-section" id="informasi" aria-labelledby="trans-informasi"><header class="trans-section-head"><span>04</span><div><h2 id="trans-informasi">Keterbukaan Informasi</h2><p>Informasi publik, materi layanan, dan landasan kebijakan.</p></div></header><div class="trans-grid"><a class="trans-card" href="/laporan-pelayanan-informasi"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Laporan Pelayanan Informasi Publik</h3><p>Pelaksanaan layanan keterbukaan informasi publik.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/e-brosur"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>E-Brosur</h3><p>Materi informasi layanan dalam format digital.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a><a class="trans-card" href="/peraturan-kebijakan"><span class="trans-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h7l4 4v14H7z"/><path d="M14 3v5h5M10 12h5M10 16h5"/></svg></span><h3>Peraturan dan Kebijakan</h3><p>Rujukan kebijakan dan regulasi yang berlaku.</p><span class="trans-more">Lihat informasi <span aria-hidden="true">→</span></span></a></div></section><aside class="trans-cta" aria-labelledby="trans-help"><div><span class="trans-kicker">Bantuan Informasi</span><h2 id="trans-help">Belum menemukan dokumen yang dicari?</h2><p>Ajukan permohonan informasi melalui PPID atau hubungi Pengadilan Negeri Natuna.</p></div><div class="trans-cta-actions"><a href="/permohonan-informasi">Layanan PPID</a><a href="/hubungi-kami">Hubungi kami</a></div></aside></div>', `fulltext` = ''
WHERE id = 45 AND alias = 'transparansi-landing';
COMMIT;
